# OpenGameKit Map Format
NAME "Crimson Nexus"

# ============================================================================
#  ASSETS
# ============================================================================

TEXTURE tiles      assets/textures/blue_tiles.png
TEXTURE corrugate  assets/textures/corrugate.png
TEXTURE concrete   assets/textures/gray_concrete.png
TEXTURE crate      assets/textures/crate_128.png
TEXTURE bricks     assets/textures/dark_bricks.png

GEOMETRY crate     assets/models/crate.obj

# ============================================================================
#  MATERIALS
# ============================================================================

MATERIAL mat_tiles      tiles      NULL (1,1,1)
MATERIAL mat_corrugate  corrugate  NULL (1,1,1)
MATERIAL mat_concrete   concrete   NULL (1,1,1)
MATERIAL mat_crate      crate      NULL (1,1,1)
MATERIAL mat_bricks     bricks     NULL (1,1,1)

# tinted variants
MATERIAL mat_bricks_red   bricks     NULL (1,0.38,0.32)
MATERIAL mat_bricks_dark  bricks     NULL (0.4,0.18,0.16)
MATERIAL mat_corr_red     corrugate  NULL (1,0.48,0.42)
MATERIAL mat_corr_rust    corrugate  NULL (0.7,0.42,0.38)
MATERIAL mat_trim_dark    concrete   NULL (0.32,0.33,0.38)
MATERIAL mat_floor_main   concrete   NULL (0.65,0.66,0.7)

# ============================================================================
#  GEOMETRY - 120x120 arena, multi-level deathmatch layout
# ============================================================================
#  Y-levels: floor=0, low platforms=3, mid platforms=6, high towers=9-12
#  Four corner towers, center nexus, two cross-corridors, scattered cover.
#  All positions symmetric for balanced spawns.

# ---- MAIN FLOOR ------------------------------------------------------------
# center 60x60 blue tiles, outer 30-unit band concrete
INSTANCE plane mat_tiles      15.0 (0,0,0)      (30,1,30)   (0,0,0)
INSTANCE plane mat_floor_main 12.0 (0,0,-45)    (60,1,15)   (0,0,0)
INSTANCE plane mat_floor_main 12.0 (0,0,45)     (60,1,15)   (0,0,0)
INSTANCE plane mat_floor_main 12.0 (-45,0,0)    (15,1,30)   (0,0,0)
INSTANCE plane mat_floor_main 12.0 (45,0,0)     (15,1,30)   (0,0,0)
INSTANCE plane mat_floor_main  8.0 (-45,0,-45)  (15,1,15)   (0,0,0)
INSTANCE plane mat_floor_main  8.0 (45,0,-45)   (15,1,15)   (0,0,0)
INSTANCE plane mat_floor_main  8.0 (-45,0,45)   (15,1,15)   (0,0,0)
INSTANCE plane mat_floor_main  8.0 (45,0,45)    (15,1,15)   (0,0,0)

# ---- PERIMETER WALLS (height 12) -------------------------------------------
INSTANCE cube mat_bricks_red  8.0 (0,6,-60.5)   (60.5,6,0.5)  (0,0,0)
INSTANCE cube mat_bricks_red  8.0 (0,6,60.5)    (60.5,6,0.5)  (0,0,0)
INSTANCE cube mat_bricks_red  8.0 (-60.5,6,0)   (0.5,6,60.5)  (0,0,0)
INSTANCE cube mat_bricks_red  8.0 (60.5,6,0)    (0.5,6,60.5)  (0,0,0)

# corrugated top band
INSTANCE cube mat_corrugate  10.0 (0,10.5,-59.8) (60,1.5,0.2) (0,0,0)
INSTANCE cube mat_corrugate  10.0 (0,10.5,59.8)  (60,1.5,0.2) (0,0,0)
INSTANCE cube mat_corrugate  10.0 (-59.8,10.5,0) (0.2,1.5,60) (0,0,0)
INSTANCE cube mat_corrugate  10.0 (59.8,10.5,0)  (0.2,1.5,60) (0,0,0)

# kick plate
INSTANCE cube mat_trim_dark   6.0 (0,0.3,-59.4)  (60,0.3,0.6) (0,0,0)
