INSTANCE cube mat_trim_dark   6.0 (59.4,0.3,0)   (0.6,0.3,60) (0,0,0)

# ---- CENTER NEXUS (elevated podium with ramps) ------------------------------
INSTANCE cube mat_bricks       4.0 (0,1.5,0)     (9,1.5,9)    (0,0,0)
INSTANCE cube mat_tiles        3.0 (0,3.05,0)    (7.5,0.05,7.5) (0,0,0)
INSTANCE cube mat_corr_red     2.0 (0,4.2,0)     (2,1.2,2)    (0,0,0)  # center pillar

# ramps to nexus (4 cardinal directions)
INSTANCE cube mat_concrete     3.0 (0,0.75,-13)  (4,0.75,1.5) (0,0,0)  # step 1 north
INSTANCE cube mat_concrete     3.0 (0,1.5,-10.5) (4,1.5,1)    (0,0,0)  # step 2
INSTANCE cube mat_concrete     3.0 (0,0.75,13)   (4,0.75,1.5) (0,0,0)  # south
INSTANCE cube mat_concrete     3.0 (0,1.5,10.5)  (4,1.5,1)    (0,0,0)
INSTANCE cube mat_concrete     3.0 (-13,0.75,0)  (1.5,0.75,4) (0,0,0)  # west
INSTANCE cube mat_concrete     3.0 (-10.5,1.5,0) (1,1.5,4)    (0,0,0)
INSTANCE cube mat_concrete     3.0 (13,0.75,0)   (1.5,0.75,4) (0,0,0)  # east
INSTANCE cube mat_concrete     3.0 (10.5,1.5,0)  (1,1.5,4)    (0,0,0)

# ---- CORNER TOWERS (4 symmetric, heights 9-12) -----------------------------
